<?php declare(strict_types=1);$editing=$product!==null;$selected=explode(',',(string)($product['billing_types']??'PIX')); ?><div class="actions"><div><span class="status">ADM · Cursos</span><h1><?= $editing?'Editar curso':'Configurar curso' ?></h1><p class="meta">Defina a política comercial usada nas matrículas.</p></div><a class="button-secondary" href="<?= $escape($basePath) ?>/admin/finance/products">Cancelar</a></div><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?><section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/admin/finance/products<?= $editing?'/'.(int)$product['id']:'' ?>"><?= $csrfField ?><div class="form-grid"><div class="form-field"><label>Curso <span class="required">*</span></label><input name="name" maxlength="160" value="<?= $escape($product['name']??'') ?>" required></div><div class="form-field"><label>Disponibilidade</label><select name="unit_id"><option value="">Todas as unidades</option><?php foreach($units as$unit):?><option value="<?= (int)$unit['id'] ?>"<?= isset($product['unit_id'])&&(int)$product['unit_id']===(int)$unit['id']?' selected':'' ?>><?= $escape($unit['name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label>Valor total <span class="required">*</span></label><input name="value" type="number" min="5" step="0.01" value="<?= $editing?$escape(number_format((float)$product['value'],2,'.','')):'' ?>" required></div><div class="form-field"><label>Número de parcelas (máximo) <span class="required">*</span></label><input name="max_installments" type="number" min="1" max="60" value="<?= (int)($product['max_installments']??1) ?>" required><small>Na matrícula não será possível ultrapassar este limite.</small></div><div class="form-field"><label>Validade do link <span class="required">*</span></label><select name="minutes_to_expire" required><?php foreach([30=>'30 minutos',60=>'1 hora',360=>'6 horas',720=>'12 horas',1440=>'24 horas']as$value=>$label):?><option value="<?= $value ?>"<?= (int)($product['minutes_to_expire']??1440)===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></div><div class="form-field form-field-full"><label>Descrição</label><textarea name="description" maxlength="500" rows="3"><?= $escape($product['description']??'') ?></textarea></div></div><fieldset><legend>Formas aceitas <span class="required">*</span></legend><div class="checks"><label><input type="checkbox" name="billing_types[]" value="PIX"<?= in_array('PIX',$selected,true)?' checked':'' ?>> Pix</label><label><input type="checkbox" name="billing_types[]" value="CREDIT_CARD"<?= in_array('CREDIT_CARD',$selected,true)?' checked':'' ?>> Cartão de crédito</label></div></fieldset><label class="check-option"><input type="checkbox" name="is_active" value="1"<?= !$editing||(int)$product['is_active']===1?' checked':'' ?>> Curso ativo</label><div class="form-actions"><button class="button-primary" type="submit">Salvar condições do curso</button></div></form></div></section>
